    [Xunit.Fact]
    public static void TestTheProducerIsReadInTheOrderTheFileHasIt() {
        emon.Transcriptctx.Tr t = new emon.Transcriptctx.Tr();
        System.Text.StringBuilder a = emon.Testport.NewText();
        System.Text.StringBuilder b = emon.Testport.NewText();
        System.Text.StringBuilder c = emon.Testport.NewText();
        emon.Testport.AssertEq(Transcript.TrRead(t, emon.Testport.TextBlob("{:emon-transcript 1 :producer {:engine \"tesseract\" :n 5 :version \"5.5.3\" :host \"a/b\"} :inputs [{:index 3 :length 99}] :entries []}")), 0, "reads");
        emon.Testport.AssertEq(Transcript.TrNInputs(t), 1, "one input");
        emon.Testport.AssertEq(Transcript.TrInIndex(t, 0), 3, "its index");
        emon.Testport.AssertEq(Transcript.TrInLength(t, 0), 99, "its length");
        emon.Testport.AssertEq(Transcript.TrPMore(t, 0), 1, "a producer");
        TtPText(t, 0, a);
        emon.Testport.AssertText(a, "engine=tesseract", "the first");
        int p1 = Transcript.TrPNext(t, 0);
        TtPText(t, p1, b);
        emon.Testport.AssertText(b, "version=5.5.3", "the second string");
        int p2 = Transcript.TrPNext(t, p1);
        TtPText(t, p2, c);
        emon.Testport.AssertText(c, "host=a/b", "the third");
        int p3 = Transcript.TrPNext(t, p2);
        emon.Testport.AssertEq(Transcript.TrPMore(t, p3), 0, "and no more");
    }
