    internal static int TtFoundAt(emon.Transcriptctx.Tr t, emon.Port.Cells k, int at, int cnt) {
        // The place of the entry a request finds, or -1.
        int e = Transcript.TrFind(t, k, at, cnt);
        if (e < 0) {
            return -1;
        }
        return Transcript.TrEN(t, e);
    }
    internal static int TtFound(emon.Transcriptctx.Tr t, emon.Port.Cells k) {
        return TtFoundAt(t, k, 0, 4);
    }
    internal static int TtTaken(emon.Transcriptctx.Tr t, emon.Port.Cells k) {
        // The place of the entry a request takes (and marks used), or -1.
        int e = Transcript.TrTake(t, k, 0, 4);
        if (e < 0) {
            return -1;
        }
        return Transcript.TrEN(t, e);
    }
    internal static int TtPair(emon.Port.Cells c, int index, int length) {
        emon.Port.CellsPush(c, index);
        emon.Port.CellsPush(c, length);
        return 0;
    }
