    internal static int TtCorpusRow(int emonT, byte[] b, int row) {
        // A transcript of the repository: it reads, it writes the same bytes, and every entry is found by its own request.
        emon.Transcriptctx.Tr t = new emon.Transcriptctx.Tr();
        System.Text.StringBuilder @out = emon.Testport.NewText();
        emon.Port.Cells k = emon.Port.NewCells();
        int e = 0;
        int n = 0;
        emon.Testport.AssertEqAt(Transcript.TrRead(t, b), 0, "the transcript reads", row);
        Transcript.TrWrite(t, @out);
        emon.Testport.AssertTextSpan(@out, b, 0, emon.Port.BlobLen(b), "read and written again, the same bytes", row);
        Transcript.TrIndex(t);
        while (Transcript.TrEMore(t, e) == 1) {
            emon.Port.CellsDrop(k, 0);
            int q = Transcript.TrEReq(t, e);
            int ql = Transcript.TrEReqLen(t, e);
            int i = 0;
            while (i < ql) {
                emon.Port.CellsPush(k, Transcript.TrECell(t, q + i));
                i += 1;
            }
            emon.Testport.AssertThatAt(Transcript.TrTake(t, k, 0, ql) >= 0, "an entry is found by its own request", row);
            n += 1;
            e = Transcript.TrENext(t, e);
        }
        emon.Testport.AssertThatAt(Transcript.TrUnused(t) <= n, "no more unused than entries", row);
        return n;
    }
    internal static int TtLineEnd(byte[] b, int from) {
        // The byte offset of the end of the line starting at `from`.
        int n = emon.Port.BlobLen(b);
        int i = from;
        while ((i < n) && (emon.Port.BlobU8(b, i) != 10)) {
            i += 1;
        }
        return i;
    }
    [Xunit.Fact]
    public static void TestEveryCommittedTranscriptIsReadAndWrittenAgainByteForByte() {
        byte[] names = emon.Testport.TestFile("transcript/manifest.txt");
        int n = emon.Port.BlobLen(names);
        int at = 0;
        int row = 0;
        while (at < n) {
            int e = TtLineEnd(names, at);
            if (e > at) {
                TtCorpusRow(0, emon.Testport.TestFileSpan(names, at, e), row);
                row += 1;
            }
            at = e + 1;
        }
        emon.Testport.AssertEq(row, 100, "the transcripts under test/");
    }
}
